Run with: cargo run -p context-graph-causal-agent --example test_llm --features cuda use std::time::Instant; use context_graph_causal_agent::llm::{CausalDiscoveryLLM, LlmConfig}; #[tokio::main] async fn main() -> Result<(), Box<dyn std::error::Error>> { // Initialize tracing tracing_subscriber::fmt() .with_max_level(tracing::Level::INFO) .init(); println!("╔═══════════════════════════════════════════════════════════════╗"); println!("║ Causal Discovery LLM Integration Test (Hermes 2 Pro) ║"); println!("╚═══════════════════════════════════════════════════════════════╝
"); // Find workspace root let mut workspace_root = std::env::current_dir()?; while !workspace_root.join("models").exists() { if !workspace_root.pop() { return Err("Could not find workspace root".into()); } } let model_dir = workspace_root.join("models/hermes-2-pro"); let config = LlmConfig { model_path: model_dir.join("Hermes-2-Pro-Mistral-7B.Q5_K_M.gguf"), causal_grammar_path: model_dir.join("causal_analysis.gbnf"), graph_grammar_path: model_dir.join("graph_relationship.gbnf"), validation_grammar_path: model_dir.join("validation.gbnf"), n_gpu_layers: u32::MAX, // Full GPU offload temperature: 0.0, // Deterministic max_tokens: 256, ..Default::default() }; println!("Configuration:"); println!(" Model: {:?}", config.model_path); println!(" GPU Layers: {} (MAX = all)", config.n_gpu_layers); println!(" Temperature: {}", config.temperature); println!(" Max Tokens: {}", config.max_tokens); println!(); // Create LLM let llm = CausalDiscoveryLLM::with_config(config)?; // Load model println!("Loading model..."); let start = Instant::now(); llm.load().await?; println!("✓ Model loaded in {:?}
", start.elapsed()); // Test cases let test_cases = [ ( "The server ran out of memory", "The application crashed with an OOM error", "Expected: A causes B (memory exhaustion leads to crash)", ), ( "We deployed a new version of the API", "Users reported faster response times", "Expected: A causes B (deployment improved performance)", ), ( "It was raining outside", "The database query was slow", "Expected: No causal relationship (unrelated events)", ), ]; println!("Running {} test cases:
", test_cases.len()); for (i, (statement_a, statement_b, expected)) in test_cases.iter().enumerate() { println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"); println!("Test Case #{}", i + 1); println!("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"); println!("Statement A: {}", statement_a); println!("Statement B: {}", statement_b); println!("{}
", expected); let start = Instant::now(); match llm .analyze_causal_relationship(statement_a, statement_b) .await { Ok(result) => { let elapsed = start.elapsed(); println!("Result:"); println!(" Has Causal Link: {}", result.has_causal_link); println!(" Confidence: {:.2}", result.confidence); println!(" Direction: {:?}", result.direction); println!(" Mechanism: {}", result.mechanism); println!(" Time: {:?}", elapsed); } Err(e) => { println!("Error: {:?}", e); } } println!(); } println!("╔═══════════════════════════════════════════════════════════════╗"); println!("║ Test Complete ║"); println!("╚═══════════════════════════════════════════════════════════════╝"); Ok(()) }

Copy EXACTLY those characters: text_excerpt = input[start_char:end_char] ADDITIONAL RULES: - span_type indicates which part: "full" (entire relationship), "cause", or "effect" - Each relationship MUST have at least one source_span - Verify character offsets are accurate before outputting - If relationship spans multiple sentences, use span_type "full" - Truncate text_excerpt to 200 characters if needed EXPLANATION REQUIREMENTS (CRITICAL FOR E5 EMBEDDING): The explanation is embedded via E5 asymmetric similarity for causal search. REQUIRED FORMAT (2 PARAGRAPHS, 40-60 WORDS TOTAL): PARAGRAPH 1: State cause-effect with SPECIFIC mechanism. BAD (vague, no mechanism): "Stress causes memory problems. This is harmful." ✗ No mechanism details, useless for search GOOD (specific mechanism): "Chronic stress activates the HPA axis, elevating cortisol which binds to hippocampal glucocorticoid receptors, triggering oxidative stress and reduced BDNF expression.

This impairs synaptic plasticity and long-term potentiation, degrading memory encoding and consolidation over time." ✓ Named: HPA axis, glucocorticoid, BDNF, synaptic plasticity, LTP EXTRACT ALL RELATIONSHIPS: - If text mentions "A causes B" and "B causes C", extract BOTH relationships - If text mentions feedback loops, extract as bidirectional relationship - If text has no causal content, return {"relationships": [], "has_causal_content": false} CONFIDENCE: - 0.9-1.0: Explicit causal language ("causes", "leads to", "results in") - 0.7-0.8: Strong implicit causation - 0.5-0.6: Possible causation, weaker indicators - <0.5: Do not include (skip uncertain relationships) MECHANISM TYPES: - "direct": A directly causes B without intermediaries - "mediated": A causes X which causes B (indirect pathway) - "feedback": A and B mutually reinforce each other (loops) - "temporal": A precedes B in a necessary sequence EXAMPLES: Input: "High cortisol from chronic stress damages hippocampal neurons, leading to memory problems." Output: { "relationships": [ { "cause": "Chronic stress elevates cortisol levels", "effect": "Elevated cortisol damages hippocampal neurons", "explanation": "Chronic psychological stress triggers sustained activation of the HPA axis, resulting in persistently elevated cortisol levels.

This glucocorticoid excess causes oxidative stress and reduces synaptic plasticity in hippocampal neurons.", "confidence": 0.85, "mechanism_type": "mediated", "source_spans": [ { "start_char": 0, "end_char": 56, "text_excerpt": "High cortisol from chronic stress damages hippocampal neurons", "span_type": "full" } ] }, { "cause": "Hippocampal neuron damage", "effect": "Memory impairment", "explanation": "The hippocampus is critical for memory formation and consolidation. /// /// Unlike [`build_single_text_prompt`](Self::build_single_text_prompt) which /// returns a single hint, this extracts every distinct cause-effect /// relationship from the content, each with its own explanatory paragraph. pub fn build_analysis_prompt_with_examples(&self, memory_a: &str, memory_b: &str) -> String { // CAUSAL-M1 FIX: Sanitize user content to prevent prompt injection let truncated_a = Self::sanitize_content(&self.truncate_content(memory_a)); let truncated_b = Self::sanitize_content(&self.truncate_content(memory_b)); format!( r#"<|im_start|>system {} <|im_end|> <|im_start|>user Example 1: A: "Aspirin inhibits cyclooxygenase enzymes" B: "Reduced prostaglandin synthesis decreases inflammation" Answer: {{"causal_link":true,"direction":"A_causes_B","confidence":0.85,"mechanism":"Aspirin's COX inhibition reduces prostaglandin production, which mediates inflammation.","mechanism_type":"mediated"}} Example 2: A: "Patients showed improved cognitive function" B: "The drug crosses the blood-brain barrier" Answer: {{"causal_link":true,"direction":"B_causes_A","confidence":0.75,"mechanism":"BBB crossing enables drug delivery to neurons, improving function.","mechanism_type":"direct"}} Example 3: A: "Chronic stress elevates cortisol levels" B: "High cortisol impairs hippocampal neurogenesis" Answer: {{"causal_link":true,"direction":"A_causes_B","confidence":0.80,"mechanism":"Stress-induced cortisol elevation damages hippocampal neurons.","mechanism_type":"mediated"}} Example 4: A: "Inflammation increases pain sensitivity" B: "Pain triggers stress response which worsens inflammation" Answer: {{"causal_link":true,"direction":"bidirectional","confidence":0.75,"mechanism":"Pain and inflammation form a positive feedback loop.","mechanism_type":"feedback"}} Example 5: A: "The patient has blue eyes" B: "The tumor was malignant" Answer: {{"causal_link":false,"direction":"none","confidence":0.00,"mechanism":"Eye color and tumor malignancy are biologically unrelated.","mechanism_type":"direct"}} Now analyze: A: "{}" B: "{}" <|im_end|> <|im_start|>assistant "#, self.system_prompt, truncated_a, truncated_b ) } } #[cfg(test)] mod tests { use super::*; #[test] fn test_build_analysis_prompt() { let builder = CausalPromptBuilder::new(); let prompt = builder.build_analysis_prompt("Event A occurred", "Event B followed"); assert!(prompt.contains("<|im_start|>system")); assert!(prompt.contains("Event A occurred")); assert!(prompt.contains("Event B followed")); assert!(prompt.contains("causal_link")); } #[test] fn test_truncate_content() { let builder = CausalPromptBuilder::new().with_max_content_length(50); let short = "This is a short string"; assert_eq!(builder.truncate_content(short), short); let long = "This is a much longer string that exceeds the maximum content length limit"; let truncated = builder.truncate_content(long); assert!(truncated.len() <= 55); // 50 + "..." assert!(truncated.ends_with("...")); } #[test] fn test_build_batch_prompt() { let builder = CausalPromptBuilder::new(); let pairs = vec![ ("A1".to_string(), "B1".to_string()), ("A2".to_string(), "B2".to_string()), ]; let prompt = builder.build_batch_prompt(&pairs); assert!(prompt.contains("Pair 1:")); assert!(prompt.contains("Pair 2:")); assert!(prompt.contains("A1")); assert!(prompt.contains("B2")); } }

The session starts fresh with valid output #[test] fn test_graceful_handling_previous_session_not_found() { let temp_dir = TempDir::new().expect("Failed to create temp dir"); let db_path = temp_dir.path(); let session_id = generate_test_session_id("session-not-found"); let fake_previous = "fake-previous-session-that-does-not-exist"; let input = create_session_start_input(&session_id, "/tmp", "resume", Some(fake_previous)); let result = invoke_hook_with_stdin( "session-start", &session_id, &["--previous-session-id", fake_previous], &input, db_path, ); // CLI is resilient: logs warning and starts fresh instead of failing assert_eq!( result.exit_code, EXIT_SUCCESS, "Non-existent previous_session_id should gracefully start fresh.
stdout: {}
stderr: {}", result.stdout, result.stderr ); // Verify warning is logged about missing session // The CLI logs: "cache is cold, cannot link to previous session" with previous_session_id let stderr_lower = result.stderr.to_lowercase(); assert!( stderr_lower.contains("previous session not found") || stderr_lower.contains("starting fresh") || stderr_lower.contains("cannot link to previous session") || stderr_lower.contains("cache is cold"), "Should log warning about missing previous session.
stderr: {}", result.stderr ); // Verify output indicates success if let Ok(json) = result.parse_stdout() { assert_eq!( json.get("success").and_then(|v| v.as_bool()), Some(true), "Output should show success=true" ); } log_test_evidence( "test_graceful_handling_previous_session_not_found", "graceful_degradation", &session_id, result.exit_code, result.execution_time_ms, false, Some(json!({ "fake_previous_session": fake_previous, "behavior": "graceful_degradation", "exit_code": result.exit_code, })), ); } // ============================================================================= // Exit Code Consistency Tests // ============================================================================= /// Test that error responses contain required fields #[test] fn test_error_response_format() { let temp_dir = TempDir::new().expect("Failed to create temp dir"); let db_path = temp_dir.path(); // Trigger an error by using empty session_id let result = invoke_hook_with_stdin("session-start", "", &[], "{}", db_path); // Should have non-zero exit code assert_ne!( result.exit_code, EXIT_SUCCESS, "Invalid input should return non-zero exit code" ); // Try to parse output as JSON if let Ok(json) = result.parse_stdout() { // Error response should have success=false if let Some(success) = json.get("success") { assert_eq!( success.as_bool(), Some(false), "Error response should have success=false" ); } // Should have an error indicator let has_error = json.get("error").is_some() || json.get("message").is_some() || json.get("code").is_some(); assert!( has_error || json.get("success").and_then(|v| v.as_bool()) == Some(false), "Error response should have error indicator" ); } log_test_evidence( "test_error_response_format", "error_format", "", result.exit_code, result.execution_time_ms, false, Some(json!({ "exit_code": result.exit_code, "has_stdout": !result.stdout.is_empty(), "has_stderr": !result.stderr.is_empty(), })), ); } /// Test that stderr contains JSON for error cases #[test] fn test_stderr_json_for_errors() { let temp_dir = TempDir::new().expect("Failed to create temp dir"); let db_path = temp_dir.path(); // Trigger an error let result = invoke_hook_with_stdin("session-start", "", &[], "invalid json {", db_path); // stderr should not be empty for errors if result.exit_code != EXIT_SUCCESS { // Either stdout or stderr should have content let has_output = !result.stdout.is_empty() || !result.stderr.is_empty(); assert!( has_output, "Error case should produce output in stdout or stderr" ); } log_test_evidence( "test_stderr_json_for_errors", "stderr_format", "", result.exit_code, result.execution_time_ms, false, Some(json!({ "stderr_len": result.stderr.len(), "stdout_len": result.stdout.len(), })), ); }
